'use strict';
function buildWalkUrl(ids,queries,mode){
 if(!Array.isArray(ids)||ids.length!==3||new Set(ids).size!==3||!['walking','driving','bicycling'].includes(mode)||ids.some(id=>!Object.prototype.hasOwnProperty.call(queries,id)||typeof queries[id]!=='string'||!queries[id]||id==='feira'))return null;
 const url=new URL('https://www.google.com/maps/dir/');url.search=new URLSearchParams({api:'1',origin:queries[ids[0]],waypoints:queries[ids[1]],destination:queries[ids[2]],travelmode:mode}).toString();return url.href;
}
