function renderWalk(){
 $('#walk-mode-label').textContent=t('Como você quer ir?');for(const[mode,label]of [['walking','A pé'],['driving','De carro'],['bicycling','De bicicleta']])$('#walk-mode option[value="'+mode+'"]').textContent=t(label);
 $('#walk-open').textContent=t('Traçar meu passeio ↗');$('#walk-order').textContent=t('O percurso começa no primeiro lugar, passa pelo segundo e termina no terceiro. Use as setas acima para mudar a ordem.');$('#walk-limit').textContent=t('O Google Maps calcula distâncias e condições. Bairros e regiões são referências aproximadas; confira os pontos e o acesso antes de sair.');
 const ids=[...chosen],url=buildWalkUrl(ids,mapQueries,$('#walk-mode').value),link=$('#walk-open');if(url){link.href=url;link.removeAttribute('aria-disabled');link.removeAttribute('tabindex')}else{link.removeAttribute('href');link.setAttribute('aria-disabled','true');link.setAttribute('tabindex','-1')}
 $('#walk-status').textContent=url?'':t(ids.length!==3?'Escolha três lugares para traçar seu passeio.':'A história da feira não tem endereço único. Troque por um lugar específico para traçar o passeio.');
}
function renderBehind(){
 for(const[id,key]of Object.entries({'behind-eyebrow':'Bastidores do Cloudinary','behind-title':'Como esta foto ganhou suas camadas','behind-intro':'As versões abaixo foram geradas pelo Cloudinary durante a preparação do projeto. Escolha uma foto no comparador para explorar sua receita.','behind-count':'20 fotos · 60 versões + abertura','behind-pipeline':'Processadas uma vez. Entregues pelo próprio app.','behind-quota':'As visitas usam arquivos já preparados. O comparador e o cartão não fazem pedidos ao Cloudinary. Novas preparações usam quota.'}))document.getElementById(id).textContent=t(key);
 const id=$('#lab-place').value,p=places.find(p=>p.id===id)||places[0];$('#behind-photo').textContent=t(p.title);
 $('#recipe-grid').replaceChildren(...[['original','Referência otimizada','Redimensionamento e compressão automática para servir de referência.'],['card','Recorte da galeria','Recorte de 720 × 518 com foco automático e qualidade ajustada pelo Cloudinary.'],['treated','Cor e enquadramento','Retrato de 720 × 960, saturação e tonalidade quente para o antes e depois.']].map(([variant,title,description])=>{const item=mediaRecipes[p.id][variant],card=document.createElement('article'),heading=document.createElement('h4'),desc=document.createElement('p'),metrics=document.createElement('strong'),details=document.createElement('details'),summary=document.createElement('summary'),code=document.createElement('code');card.className='recipe-card';heading.textContent=t(title);desc.textContent=t(description);metrics.textContent=item.format+' · '+new Intl.NumberFormat(currentLanguage,{maximumFractionDigits:1}).format(item.bytes/1024)+' KiB';summary.textContent=t('Ver receita de transformação');code.textContent=item.recipe;details.append(summary,code);card.append(heading,metrics,desc,details);return card}));
}
